"""Plot CSVs generated by heom_bug_dynamics.jl (requires numpy/matplotlib)."""
from pathlib import Path
import os
import tempfile

os.environ.setdefault("MPLCONFIGDIR", str(Path(tempfile.gettempdir()) / "ttn-matplotlib"))
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

HERE = Path(__file__).resolve().parent
fine = np.genfromtxt(HERE / "data" / "heom_bug_fine.csv", delimiter=",", names=True)
coarse = np.genfromtxt(HERE / "data" / "heom_bug_coarse.csv", delimiter=",", names=True)
FIGURES = HERE / "figures"
FIGURES.mkdir(parents=True, exist_ok=True)
plt.rcParams.update({"font.size": 10, "axes.spines.top": False,
                     "axes.spines.right": False, "svg.fonttype": "none"})
fig, axes = plt.subplots(2, 2, figsize=(12, 7), sharex=True, layout="constrained")
fig.suptitle("Three-mode HEOM: TTN augmented BUG", fontsize=18)
fig.supxlabel("Time (consistent with hbar = 1)")
t = fine["time"]
ax = axes[0, 0]
for level, color in ((1, "#2864b7"), (2, "#df7625")):
    ax.plot(t, fine[f"p{level}_ttn"], color=color, lw=2, label=f"TTN P({level})")
    ax.plot(t[::5], fine[f"p{level}_dense"][::5], "o", color=color,
            fillstyle="none", ms=4, label=f"Dense P({level})")
ax.set(title="Zero-tier populations", ylabel="Population")
ax.legend(ncol=2, fontsize=9)
ax = axes[0, 1]
for data, label in ((coarse, "h = 0.02"), (fine, "h = 0.01")):
    ax.semilogy(data["time"][1:], np.maximum(data["density_error"][1:], 1e-18), label=label)
ax.set(title="Density error against dense ADO exponential", ylabel=r"$\|\rho_0^{TTN}-\rho_0^{dense}\|_F$")
ax.legend()
ax = axes[1, 0]
ax.semilogy(t, np.maximum(fine["trace_drift"], 1e-18), label="After root correction")
ax.semilogy(t, np.maximum(fine["uncorrected_trace_drift"], 1e-18), alpha=0.75,
            label="Before root correction")
ax.set(title="Trace drift (zeros displayed at 1e-18)", ylabel=r"$|\mathrm{Tr}\,\rho_0(t)-\mathrm{Tr}\,\rho_0(0)|$")
ax.legend(fontsize=9)
ax = axes[1, 1]
ax.step(t, fine["max_rank"], where="post", color="#31845c", label="Maximum TTN bond rank")
ax.set(title="Adaptive ranks; truncation budget = 1e-10/step", ylabel="Rank")
ax.set_yticks(range(1, int(max(fine["max_rank"])) + 1))
ax.legend(fontsize=9)
for ax in axes.flat:
    ax.grid(alpha=0.22)
    ax.set_xlim(t[0], t[-1])
for suffix in ("svg", "png"):
    destination = FIGURES / f"heom_bug_dynamics.{suffix}"
    fig.savefig(destination, dpi=160)
    print(destination)
